    # 5. Frete grátis
    if valor_pedido >= 299.90 and not expresso and regiao in ["S", "SE", "CO"]:
        return 0.0

    # 6. Cupons
    desconto = 0.0
    if cupom is not None and str(cupom).strip() != "":
        cupom_lower = cupom.lower()
        if cupom_lower == "frete10":
            desconto = 0.10
        elif cupom_lower == "fretemetade":
            if peso_kg > 5:
                # Cupom ignorado (desconto 0)
                desconto = 0.0
            else:
                desconto = 0.50
        else:
            raise ValueError("Cupom inválido.")
    else:
        desconto = 0.0

    # 7. Frete mínimo
    # Calculamos o valor com desconto usando Decimal para precisão monetária
    tarifa_final = Decimal(str(tarifa_base)) * (Decimal('1') - Decimal(str(desconto)))

    if tarifa_final < 9.90:
        tarifa_final = Decimal('9.90')

    # 8. Arredondamento e Retorno
    return float(tarifa_final.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))
